#include "synchronizationdialog.h"
#include <QCheckBox>
#include <QComboBox>
#include <QDir>
#include <QFormLayout>
#include <QHeaderView>
#include <QHash>
#include <QLabel>
#include <QPlainTextEdit>
#include <QPushButton>
#include <QSignalBlocker>
#include <QTreeWidget>
#include <QVBoxLayout>
SynchronizationDialog::SynchronizationDialog(SynchronizationRequest request,QWidget *parent):QDialog(parent),m_request(std::move(request)){
    setObjectName("synchronizationDialog");setWindowTitle(tr("Sincronizar por cópia"));resize(1100,770);auto *layout=new QVBoxLayout(this);auto *hint=new QLabel(tr("Escolha a direção e revise as cópias. Não propaga exclusões. Por padrão copia itens faltantes e preserva conflitos. Uma pasta faltante inclui os descendentes selecionados, copiados uma única vez com seu conteúdo atual na execução. O plano e os destinos serão revalidados; interrupção pode preservar cópias já concluídas. Até 256 origens por plano."),this);hint->setWordWrap(true);layout->addWidget(hint);auto *form=new QFormLayout;layout->addLayout(form);auto *roots=new QLabel(tr("Esquerda: %1\nDireita: %2").arg(QDir::toNativeSeparators(m_request.left),QDir::toNativeSeparators(m_request.right)),this);roots->setTextFormat(Qt::PlainText);roots->setWordWrap(true);roots->setTextInteractionFlags(Qt::TextSelectableByMouse);form->addRow(roots);
    m_direction=new QComboBox(this);m_direction->setObjectName("syncDirection");m_direction->addItems({tr("Esquerda → Direita"),tr("Direita → Esquerda")});m_direction->setCurrentIndex(m_request.toRight?0:1);form->addRow(tr("Copiar de:"),m_direction);m_include=new QCheckBox(tr("Incluir diferenças entre arquivos existentes (revisar conflitos)"),this);m_include->setObjectName("syncIncludeConflicts");m_include->setChecked(m_request.includeConflicts);form->addRow(m_include);m_conflicts=new QComboBox(this);m_conflicts->setObjectName("syncConflicts");m_conflicts->addItems({tr("Manter as duas versões, criando outro nome"),tr("Perguntar no Windows antes de substituir")});m_conflicts->setCurrentIndex(m_request.conflict==OperationConflict::KeepBoth?0:1);m_conflicts->setEnabled(m_request.includeConflicts);form->addRow(tr("Conflitos:"),m_conflicts);
    m_rows=new QTreeWidget(this);m_rows->setObjectName("syncRows");m_rows->setColumnCount(3);m_rows->setHeaderLabels({tr("Incluir / caminho"),tr("Destino previsto"),tr("Ação / impedimento")});m_rows->setRootIsDecorated(false);m_rows->setUniformRowHeights(true);m_rows->header()->setSectionResizeMode(0,QHeaderView::Stretch);m_rows->header()->setSectionResizeMode(1,QHeaderView::Stretch);m_rows->header()->setSectionResizeMode(2,QHeaderView::Stretch);for(int i=0;i<m_request.entries.size();++i){auto *row=new QTreeWidgetItem(m_rows,{m_request.entries[i].relativePath,{},{}});row->setToolTip(0,m_request.entries[i].relativePath);row->setData(0,Qt::UserRole,i);row->setCheckState(0,Qt::Checked);}layout->addWidget(m_rows,1);
    m_details=new QPlainTextEdit(this);m_details->setObjectName("syncDetails");m_details->setReadOnly(true);m_details->setMaximumHeight(100);layout->addWidget(m_details);m_status=new QLabel(this);m_status->setObjectName("syncStatus");m_status->setWordWrap(true);m_status->setTextFormat(Qt::PlainText);layout->addWidget(m_status);m_confirm=new QCheckBox(tr("Revisei a direção, os destinos e os conflitos desta prévia."),this);m_confirm->setObjectName("syncConfirm");layout->addWidget(m_confirm);auto *buttons=new QHBoxLayout;layout->addLayout(buttons);m_preview=new QPushButton(tr("Gerar prévia"),this);m_preview->setObjectName("syncPreview");m_apply=new QPushButton(tr("Aplicar cópias (Windows)"),this);m_apply->setObjectName("syncApply");m_cancel=new QPushButton(tr("Cancelar trabalho"),this);m_cancel->setObjectName("syncCancel");for(auto *button:{m_preview,m_apply,m_cancel}){button->setAutoDefault(false);buttons->addWidget(button);}buttons->addStretch();auto *close=new QPushButton(tr("Fechar"),this);buttons->addWidget(close);connect(close,&QPushButton::clicked,this,&SynchronizationDialog::reject);connect(m_cancel,&QPushButton::clicked,this,[this]{if(m_job){m_job->cancel();m_cancel->setEnabled(false);m_status->setText(tr("Aguardando o trabalho encerrar; cópias já concluídas serão preservadas."));}});connect(m_preview,&QPushButton::clicked,this,&SynchronizationDialog::preview);connect(m_apply,&QPushButton::clicked,this,&SynchronizationDialog::apply);connect(m_direction,&QComboBox::currentIndexChanged,this,&SynchronizationDialog::invalidate);connect(m_conflicts,&QComboBox::currentIndexChanged,this,&SynchronizationDialog::invalidate);connect(m_include,&QCheckBox::toggled,this,[this](bool checked){m_conflicts->setEnabled(checked);invalidate();});connect(m_rows,&QTreeWidget::itemChanged,this,[this](QTreeWidgetItem*,int column){if(column==0)invalidate();});connect(m_confirm,&QCheckBox::toggled,this,[this](bool value){m_apply->setEnabled(value&&!m_job&&!m_applied&&m_plan.valid());});preview();
}
SynchronizationDialog::~SynchronizationDialog(){if(m_job){m_job->cancel();m_job->wait();}}
void SynchronizationDialog::reject(){if(m_job){m_closePending=true;m_job->cancel();m_status->setText(tr("Aguardando o encerramento antes de fechar…"));return;}QDialog::reject();}
void SynchronizationDialog::invalidate(){if(m_job||m_applied)return;m_plan={};m_confirm->setChecked(false);m_apply->setEnabled(false);const QSignalBlocker block(m_rows);for(int i=0;i<m_rows->topLevelItemCount();++i){m_rows->topLevelItem(i)->setText(1,{});m_rows->topLevelItem(i)->setToolTip(1,{});m_rows->topLevelItem(i)->setToolTip(2,{});m_rows->topLevelItem(i)->setText(2,tr("Gerar outra prévia"));}m_status->setText(tr("Opções alteradas; gere outra prévia antes de aplicar."));}
void SynchronizationDialog::setBusy(bool busy){for(auto *widget:QList<QWidget*>{m_direction,m_include,m_rows,m_preview})widget->setEnabled(!busy&&!m_applied);m_conflicts->setEnabled(!busy&&!m_applied&&m_include->isChecked());m_confirm->setEnabled(!busy&&!m_applied);m_apply->setEnabled(!busy&&!m_applied&&m_confirm->isChecked()&&m_plan.valid());m_cancel->setEnabled(busy);}
void SynchronizationDialog::preview(){
    if(m_job||m_applied)return;auto request=m_request;request.entries.clear();for(int i=0;i<m_rows->topLevelItemCount();++i){const auto *row=m_rows->topLevelItem(i);if(row->checkState(0)==Qt::Checked)request.entries.append(m_request.entries[row->data(0,Qt::UserRole).toInt()]);}request.toRight=m_direction->currentIndex()==0;request.includeConflicts=m_include->isChecked();request.conflict=m_conflicts->currentIndex()==0?OperationConflict::KeepBoth:OperationConflict::Ask;request.ownerWindow=request.nativeUi?quintptr(winId()):0;m_plan={};m_confirm->setChecked(false);m_applying=false;m_status->setText(tr("Preparando e conferindo a prévia atual…"));m_job=new SynchronizationJob(std::move(request),this);setBusy(true);connect(m_job,&QThread::finished,this,&SynchronizationDialog::finish);m_job->start();
}
void SynchronizationDialog::apply(){if(m_job||m_applied||!m_confirm->isChecked()||!m_plan.valid())return;m_applying=true;m_job=new SynchronizationJob(m_plan,this);setBusy(true);m_status->setText(tr("Aplicando cópias e revalidando o plano…"));connect(m_job,&SynchronizationJob::progress,this,[this](quint32 total,quint32 done,const QString &path){m_status->setText(tr("%1 de %2 origens processadas. %3").arg(done).arg(total).arg(path));});connect(m_job,&QThread::finished,this,&SynchronizationDialog::finish);m_job->start();}
void SynchronizationDialog::finish(){
    m_job->wait();if(!m_applying){m_plan=m_job->plan();const QSignalBlocker block(m_rows);QHash<QString,QTreeWidgetItem*> rows;for(int i=0;i<m_rows->topLevelItemCount();++i){auto *row=m_rows->topLevelItem(i);rows.insert(row->text(0),row);row->setText(1,{});row->setToolTip(1,{});row->setToolTip(2,{});row->setText(2,row->checkState(0)==Qt::Checked?tr("Sem ação"):tr("Fora da seleção"));}for(const auto &item:m_plan.items)if(auto *row=rows.value(item.relativePath)){row->setText(1,QDir::toNativeSeparators(item.target));row->setText(2,item.message);row->setToolTip(1,QDir::toNativeSeparators(item.target));QString detail=item.message;if(item.transfer&&!item.transfer->sources.isEmpty()&&!(item.transfer->sources[0].attributes&0x10))detail+=tr("\nOrigem conferida: %1 bytes").arg(item.transfer->sources[0].bytes);if(item.targetIdentity&&!(item.targetIdentity->attributes&0x10))detail+=tr("\nDestino conferido: %1 bytes").arg(item.targetIdentity->bytes);row->setToolTip(2,detail);}m_status->setText(m_plan.cancelled?tr("Prévia cancelada."):!m_plan.error.isEmpty()?m_plan.error:m_plan.valid()?tr("Prévia pronta: %1 cópias. Confira as linhas e marque a confirmação.").arg(m_plan.changes()):tr("Há impedimentos ou nenhuma cópia. Desmarque linhas, ajuste as opções ou compare novamente."));}
    else{const auto result=m_job->result();m_applied=true;QString detail=result.error;for(const auto &item:result.items){const auto line="\n"+operationItemLabel(item.state)+": "+item.source+" → "+item.target+(item.error.isEmpty()?QString{}:"\n"+item.error);if(detail.size()+line.size()>512*1024){detail+="\nDetalhes da exibição limitados a 512 mil caracteres.";break;}detail+=line;}m_details->setPlainText(detail);m_status->setText((result.state==OperationState::Completed?tr("Cópias concluídas."):result.state==OperationState::Cancelled?tr("Trabalho cancelado; confira as cópias parciais."):tr("Trabalho interrompido; confira os resultados parciais."))+tr(" Origens concluídas: %1. Nenhuma exclusão propagada. Faça outra comparação antes de novo plano.").arg(result.completedCount()));}
    m_job->deleteLater();m_job=nullptr;setBusy(false);if(m_closePending)QDialog::reject();
}
